// @vitest-environment node

import { readFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { convert, emphasize, fontStyleFromName } from "./converter.js";

// Fixtures are generated by test-corpus/create-fixtures.mjs (pdf-lib) and committed.
const fixturesDir = resolve(dirname(fileURLToPath(import.meta.url)), "../../../test-corpus/fixtures");

async function convertFixture(name: string, options?: { emphasis?: boolean }): Promise<string> {
  const bytes = await readFile(resolve(fixturesDir, name));
  const result = await convert(new Uint8Array(bytes).buffer, options);
  expect(result.status).toBe("success");
  return result.markdown;
}

function markdownLinks(markdown: string): Array<{ text: string; url: string }> {
  return [...markdown.matchAll(/\[([^\]]*)\]\(([^)\s]+)\)/g)].map((m) => ({ text: m[1], url: m[2] }));
}

describe("page-scoped link matching", () => {
  it("links text only on the page that carries the annotation", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    const homeLinks = markdownLinks(markdown).filter((l) => l.url === "https://example.com/home");

    // "Project homepage" is drawn at the same spot on pages 1–3; only page 2 has the link.
    expect(homeLinks).toEqual([{ text: "Project homepage", url: "https://example.com/home" }]);
    expect(markdown.match(/Project homepage/g)).toHaveLength(3);
  });

  it("merges consecutive items that share a URL into one link", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    // "Read the" is bold and " docs" regular: one link, emphasis inside it.
    expect(markdown).toContain("[**Read the** docs](https://example.com/docs)");

    // No two links side by side on a line with the same URL.
    expect(markdown).not.toMatch(/\]\(([^)\s]+)\)[ \t]*\[[^\]]*\]\(\1\)/);
  });

  it("does not wrap a lone punctuation item that only sits inside a wider link", async () => {
    const markdown = await convertFixture("links-same-position.pdf");
    expect(markdown).not.toContain("[(]");
    expect(markdown).toContain("[see appendix](https://example.com/appendix)");
  });
});

describe("header/footer stripping stays in the header and footer bands", () => {
  it("removes footer page numbers but keeps standalone numbers in the body", async () => {
    const markdown = await convertFixture("header-footer-numbers.pdf");

    // Running header is stripped.
    expect(markdown).not.toContain("Example Annual Report");

    // Body numbers survive: TOC page numbers and table cells.
    for (const n of ["17", "23", "2022", "2023", "19"]) {
      expect(markdown).toMatch(new RegExp(`(^|[^\\d])${n}([^\\d]|$)`));
    }
    expect(markdown.match(/(^|[^\d])17([^\d]|$)/g)?.length).toBe(2);

    // Footer page numbers 1–5 are gone: no line is just a number.
    expect(markdown.split("\n").filter((line) => /^\s*\d\s*$/.test(line))).toEqual([]);
  });
});

describe("gap-aware joining of text runs", () => {
  it("joins touching runs without a space and keeps word gaps", async () => {
    const markdown = await convertFixture("touching-runs.pdf");
    expect(markdown).toContain("primitive services.");
    expect(markdown).not.toContain("services .");
    expect(markdown).toContain("Revenue grew to (46,752) last year.");
    expect(markdown).toContain("separate words stay apart.");
  });
});

describe("inline bold and italic from real font names", () => {
  it("wraps bold, italic and bold-italic runs with punctuation outside the markers", async () => {
    const markdown = await convertFixture("inline-emphasis.pdf");
    expect(markdown).toContain("The platform offers **primitive services**. It also has an *italic span*, then ***both styles*** in one line.");
  });

  it("nests italic inside an adjacent bold run instead of closing and reopening", async () => {
    const markdown = await convertFixture("inline-emphasis.pdf");
    expect(markdown).toContain("**Key *term* and its definition**: explained.");
    // Bold inside a longer italic stretch nests the other way round.
    expect(markdown).toContain("See the *Rules of Arbitration (**ICC Rules***) for details.");
    // Partly overlapping stretches split where the inner style continues.
    expect(markdown).toContain("Choose the *Amount* ***E-file* options** that apply.");
  });

  it("keeps a bold run that wraps across lines as one span", async () => {
    const markdown = await convertFixture("inline-emphasis.pdf");
    expect(markdown).toContain("**a bold phrase that wraps onto the next line** and then ends");
    expect(markdown).not.toMatch(/\*\* \*\*|\*\*\*\*/);
  });

  it("adds no markers to headings or to a line that is bold throughout", async () => {
    const markdown = await convertFixture("inline-emphasis.pdf");
    expect(markdown).toMatch(/^# Results$/m);
    expect(markdown).toMatch(/^Note: this whole line is set in bold type and ends with a full stop\.$/m);
  });

  it("emits no emphasis with emphasis: false", async () => {
    const markdown = await convertFixture("inline-emphasis.pdf", { emphasis: false });
    expect(markdown).toContain("The platform offers primitive services. It also has an italic span,");
    expect(markdown).not.toContain("*");
  });
});

describe("emphasize", () => {
  it.each([
    ["primitive services.", "**", "**primitive services**."],
    [" (see appendix) ", "*", " (*see appendix*) "],
    [", let", "*", ", *let*"],
    ["-group for some", "*", "-*group for some*"],
    ["• Item text", "**", "• **Item text**"],
    ["1. Introduction", "**", "1. **Introduction**"],
    ["NEIL (", "**", "**NEIL** ("],
    ["x", "**", "x"],
    ["(12)", "*", "(12)"],
  ])("%j with %s → %j", (text, marker, expected) => {
    expect(emphasize(text, marker)).toBe(expected);
  });
});

describe("fontStyleFromName", () => {
  it.each([
    ["NVLTZM+Helvetica-Bold", true, false],
    ["Helvetica-Oblique", false, true],
    ["Times-BoldItalic", true, true],
    ["Arial,BoldItalic", true, true],
    ["ArialMT", false, false],
    ["TimesNewRomanPS-ItalicMT", false, true],
    ["MinionPro-It", false, true],
    ["MinionPro-SemiboldIt", true, true],
    ["NimbusRomNo9L-Medi", true, false],
    ["NimbusRomNo9L-ReguItal", false, true],
    ["CMBX10", true, false],
    ["CMTI10", false, true],
    ["CMMI10", false, false],
    ["CMR10", false, false],
    ["Calibri-Light", false, false],
    ["DigitalSans", false, false],
  ])("%s → bold %s, italic %s", (name, bold, italic) => {
    expect(fontStyleFromName(name)).toEqual({ bold, italic });
  });
});

describe("binary input types", () => {
  const fixture = () => readFile(resolve(fixturesDir, "links-same-position.pdf"));

  it("accepts a Node Buffer as returned by fs.readFile", async () => {
    const buffer = await fixture();
    const result = await convert(buffer);
    expect(result.status).toBe("success");
    expect(result.markdown).toContain("Project homepage");
    expect(buffer.byteLength).toBeGreaterThan(0);
  });

  it("accepts a Uint8Array view and leaves the caller's buffer attached", async () => {
    const bytes = new Uint8Array(await fixture());
    const length = bytes.buffer.byteLength;
    const result = await convert(bytes);
    expect(result.status).toBe("success");
    expect(bytes.buffer.byteLength).toBe(length);
  });

  it("accepts an ArrayBuffer and leaves it attached", async () => {
    const arrayBuffer = new Uint8Array(await fixture()).buffer;
    const length = arrayBuffer.byteLength;
    const result = await convert(arrayBuffer);
    expect(result.status).toBe("success");
    expect(arrayBuffer.byteLength).toBe(length);
  });

  it("returns parse_failed, not a throw, for non-PDF bytes in a Buffer", async () => {
    const result = await convert(Buffer.from("not a pdf"));
    expect(result.status).toBe("failed");
    expect(result.messages[0]?.code).toBe("parse_failed");
  });
});
